import app from 'flarum/forum/app';
import PollList from '../Poll/PollList';
import PollGroupListItem from './PollGroupListItem';
export default class PollGroupList extends PollList {
  className() {
    return 'PollGroupList';
  }
  itemView(pollGroup) {
    return m(PollGroupListItem, {
      pollGroup: pollGroup,
      compactView: true
    });
  }
  emptyText() {
    return app.translator.trans('fof-polls.forum.poll_groups.list_page.empty_text');
  }
  loadMoreText() {
    return app.translator.trans('fof-polls.forum.poll_groups.list_page.load_more_button');
  }
}
flarum.reg.add('fof-polls', 'forum/components/PollGroup/PollGroupList', PollGroupList);